// Regenerates src/vendor.generated.ts: d3 and Chart.js inlined as classic
// scripts (globals `d3`, `Chart`) so generated widgets need no network.
// Run: pnpm --filter @repo/design-system vendor
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { join } from "node:path";

const pkgDir = (name) =>
  fileURLToPath(new URL(`../node_modules/${name}`, import.meta.url));
const read = (path) => readFileSync(path, "utf8");

const libs = [
  ["d3", join(pkgDir("d3"), "dist/d3.min.js")],
  ["chart.js", join(pkgDir("chart.js"), "dist/chart.umd.min.js")],
];

const tags = libs.map(([name, file]) => {
  // Strip source-map comments (no fetch under CSP) and make "</script" inert.
  const code = read(file)
    .replace(/\/\/# sourceMappingURL=.*$/gm, "")
    .replace(/<\/script/gi, "<\\/script");
  const version = JSON.parse(read(join(pkgDir(name), "package.json"))).version;
  return `<script data-vendor="${name}@${version}">${code}</script>`;
});

writeFileSync(
  new URL("../src/vendor.generated.ts", import.meta.url),
  `// GENERATED by scripts/build-vendor.mjs - do not edit.\nexport const VENDOR_LIBS_SCRIPT_TAGS = ${JSON.stringify(tags.join("\n"))};\n`
);
